check("test2(30)", () => M.test2(30), "4638144666238189568", true);
check("test2(-1.5)", () => M.test2(-1.5), "13841813454723219456", true);
check("test3(0)", () => M.test3(0), "0", true);
check("test3(0.5)", () => M.test3(0.5), "4607182418800017408", true);
check("test3(2.25)", () => M.test3(2.25), "4616752568008179712", true);
check("test3(30)", () => M.test3(30), "4633641066610819072", true);
check("test3(-1.5)", () => M.test3(-1.5), "13837309855095848960", true);
check("test4(0)", () => M.test4(0), "0", true);
check("test4(0.5)", () => M.test4(0.5), "4607182418800017408", true);
check("test4(2.25)", () => M.test4(2.25), "4616752568008179712", true);
check("test4(30)", () => M.test4(30), "4633641066610819072", true);
check("test4(-1.5)", () => M.test4(-1.5), "13837309855095848960", true);
check("test5(0)", () => M.test5(0), "0", true);
check("test5(0.5)", () => M.test5(0.5), "4607182418800017408", true);
check("test5(2.25)", () => M.test5(2.25), "4616752568008179712", true);
check("test5(30)", () => M.test5(30), "4633641066610819072", true);
check("test5(-1.5)", () => M.test5(-1.5), "13837309855095848960", true);

console.log(`EsPrecedence02-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
